import { useState, useEffect } from 'react';

interface Product {
  id: string;
  nombre: string;
  codigo: string;
  precio: number;
}

interface ErrorResponse {
  error: string;
}

export default function App() {
  const [nombre, setNombre] = useState('');
  const [codigo, setCodigo] = useState('');
  const [precio, setPrecio] = useState('');
  const [productos, setProductos] = useState<Product[]>([]);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchProductos();
  }, []);

  const fetchProductos = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/productos');
      if (!response.ok) throw new Error('Error al cargar productos');
      const data: Product[] = await response.json();
      setProductos(data);
      setError('');
    } catch (err) {
      setError('Error al cargar productos');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleGuardar = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    try {
      const response = await fetch('/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          nombre: nombre.trim(),
          codigo: codigo.trim(),
          precio: parseFloat(precio),
        }),
      });

      const data: Product | ErrorResponse = await response.json();

      if (!response.ok) {
        setError((data as ErrorResponse).error);
        return;
      }

      setProductos([...productos, data as Product]);
      setNombre('');
      setCodigo('');
      setPrecio('');
    } catch (err) {
      setError('Error al guardar producto');
      console.error(err);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 py-8 px-4">
      <div className="max-w-md mx-auto bg-white rounded-lg shadow-md p-6">
        <h1 className="text-2xl font-bold mb-6 text-gray-800">Registro de Productos</h1>

        <form onSubmit={handleGuardar} className="space-y-4 mb-6">
          <input
            type="text"
            placeholder="Nombre"
            value={nombre}
            onChange={(e) => setNombre(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
          <input
            type="text"
            placeholder="Código"
            value={codigo}
            onChange={(e) => setCodigo(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
          <input
            type="number"
            placeholder="Precio"
            value={precio}
            onChange={(e) => setPrecio(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
          <button
            type="submit"
            className="w-full bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded-lg transition duration-200"
          >
            Guardar
          </button>
        </form>

        {error && (
          <div className="mb-4 p-3 bg-red-100 border border-red-400 text-red-700 rounded-lg">
            {error}
          </div>
        )}

        {loading ? (
          <div className="text-center text-gray-500">Cargando productos...</div>
        ) : (
          <div className="space-y-2">
            <h2 className="text-lg font-semibold text-gray-800 mb-3">Productos Guardados</h2>
            {productos.length === 0 ? (
              <p className="text-gray-500 text-center">No hay productos aún</p>
            ) : (
              <ul className="space-y-2">
                {productos.map((producto) => (
                  <li
                    key={producto.id}
                    className="bg-gray-50 p-3 rounded-lg border border-gray-200"
                  >
                    <p className="font-semibold text-gray-800">{producto.nombre}</p>
                    <p className="text-sm text-gray-600">Código: {producto.codigo}</p>
                    <p className="text-sm text-gray-600">Precio: ${producto.precio.toFixed(2)}</p>
                  </li>
                ))}
              </ul>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

