import { createServer, IncomingMessage, ServerResponse } from 'node:http';

interface Product {
  id: string;
  nombre: string;
  codigo: string;
  precio: number;
}

const productos: Map<string, Product> = new Map();
let idCounter = 1;

const port = process.env.PORT || 3000;

const server = createServer((req: IncomingMessage, res: ServerResponse) => {
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    res.end();
    return;
  }

  if (req.url === '/api/productos' && req.method === 'GET') {
    const productosArray = Array.from(productos.values());
    res.writeHead(200);
    res.end(JSON.stringify(productosArray));
    return;
  }

  if (req.url === '/api/productos' && req.method === 'POST') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);
        const { nombre, codigo, precio } = data;

        // Validaciones
        if (!nombre || nombre.length < 3) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Nombre muy corto' }));
          return;
        }

        if (!codigo) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Código requerido' }));
          return;
        }

        const codigoExistente = Array.from(productos.values()).some(
          (p) => p.codigo === codigo
        );
        if (codigoExistente) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Código repetido' }));
          return;
        }

        if (typeof precio !== 'number' || precio < 0) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Precio inválido' }));
          return;
        }

        const newProduct: Product = {
          id: String(idCounter++),
          nombre,
          codigo,
          precio,
        };

        productos.set(newProduct.id, newProduct);

        res.writeHead(201);
        res.end(JSON.stringify(newProduct));
      } catch (error) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'JSON inválido' }));
      }
    });
    return;
  }

  res.writeHead(404);
  res.end(JSON.stringify({ error: 'Ruta no encontrada' }));
});

server.listen(port, () => {
  console.log(`Servidor escuchando en puerto ${port}`);
});

