import React, { useState, useEffect } from 'react';

interface Product {
  id: string;
  nombre: string;
  codigo: string;
  precio: number;
}

interface ApiError {
  error: string;
}

export default function App() {
  const [nombre, setNombre] = useState('');
  const [codigo, setCodigo] = useState('');
  const [precio, setPrecio] = useState('');
  const [productos, setProductos] = useState<Product[]>([]);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);

  // Cargar productos al montar
  useEffect(() => {
    fetchProductos();
  }, []);

  const fetchProductos = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/productos');
      if (!response.ok) throw new Error('Error al cargar productos');
      const data = await response.json();
      setProductos(data);
      setError('');
    } catch (err) {
      setError('Error al cargar los datos');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleGuardar = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!nombre.trim() || !codigo.trim() || !precio.trim()) {
      setError('Todos los campos son requeridos');
      return;
    }

    try {
      const response = await fetch('/api/productos', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          nombre: nombre.trim(),
          codigo: codigo.trim(),
          precio: parseFloat(precio),
        }),
      });

      const data: ApiError | Product = await response.json();

      if (!response.ok) {
        setError((data as ApiError).error || 'Error al guardar');
        return;
      }

      setNombre('');
      setCodigo('');
      setPrecio('');
      setError('');
      await fetchProductos();
    } catch (err) {
      setError('Error al guardar el producto');
      console.error(err);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-8">
      <div className="max-w-2xl mx-auto">
        <h1 className="text-4xl font-bold text-gray-800 mb-8">
          Registro de Productos
        </h1>

        {/* Formulario */}
        <form
          onSubmit={handleGuardar}
          className="bg-white rounded-lg shadow-lg p-6 mb-8"
        >
          <div className="space-y-4">
            <div>
              <input
                type="text"
                placeholder="Nombre"
                value={nombre}
                onChange={(e) => setNombre(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>

            <div>
              <input
                type="text"
                placeholder="Código"
                value={codigo}
                onChange={(e) => setCodigo(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>

            <div>
              <input
                type="number"
                placeholder="Precio"
                value={precio}
                onChange={(e) => setPrecio(e.target.value)}
                step="0.01"
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>

          {error && (
            <div className="mt-4 p-3 bg-red-100 border border-red-400 text-red-700 rounded-lg text-sm">
              {error}
            </div>
          )}

          <button
            type="submit"
            className="w-full mt-6 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-2 px-4 rounded-lg transition-colors"
          >
            Guardar
          </button>
        </form>

        {/* Lista de productos */}
        <div className="bg-white rounded-lg shadow-lg p-6">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">Productos</h2>

          {loading ? (
            <p className="text-gray-500">Cargando...</p>
          ) : productos.length === 0 ? (
            <p className="text-gray-500">No hay productos registrados</p>
          ) : (
            <div className="space-y-3">
              {productos.map((producto) => (
                <div
                  key={producto.id}
                  className="flex items-center justify-between p-4 bg-gray-50 rounded-lg border border-gray-200"
                >
                  <div>
                    <p className="font-semibold text-gray-800">
                      {producto.nombre}
                    </p>
                    <p className="text-sm text-gray-600">
                      Código: {producto.codigo}
                    </p>
                  </div>
                  <p className="text-indigo-600 font-bold">
                    ${producto.precio.toFixed(2)}
                  </p>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

