import { createServer, IncomingMessage, ServerResponse } from 'node:http';
import { URL } from 'node:url';

interface Product {
  id: string;
  nombre: string;
  codigo: string;
  precio: number;
}

const productos: Map<string, Product> = new Map();
let nextId = 1;

const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
  // Configurar CORS
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
  res.setHeader('Content-Type', 'application/json');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`);

  // GET /api/productos
  if (url.pathname === '/api/productos' && req.method === 'GET') {
    const productosArray = Array.from(productos.values());
    res.writeHead(200);
    res.end(JSON.stringify(productosArray));
    return;
  }

  // POST /api/productos
  if (url.pathname === '/api/productos' && req.method === 'POST') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const { nombre, codigo, precio } = JSON.parse(body);

        // Validaciones
        if (!nombre || nombre.length < 3) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Nombre muy corto' }));
          return;
        }

        if (!codigo || productos.has(codigo)) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Código repetido' }));
          return;
        }

        if (typeof precio !== 'number' || precio < 0) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Precio inválido' }));
          return;
        }

        // Crear producto
        const nuevoProducto: Product = {
          id: String(nextId++),
          nombre,
          codigo,
          precio,
        };

        productos.set(codigo, nuevoProducto);

        res.writeHead(201);
        res.end(JSON.stringify(nuevoProducto));
      } catch (error) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
    return;
  }

  // Ruta no encontrada
  res.writeHead(404);
  res.end(JSON.stringify({ error: 'Not found' }));
});

const PORT = process.env.PORT || 3000;

server.listen(PORT, () => {
  console.log(`Servidor escuchando en puerto ${PORT}`);
});
